async function s(a="Miguelangel_Monasterio_CV.pdf"){try{const e=await fetch("/resume.pdf");if(!e.ok)throw new Error(`El servidor respondió con código ${e.status}`);const r=e.headers.get("content-type")||"";if(!r.toLowerCase().includes("pdf"))throw new Error(`Respuesta inesperada (content-type=${r})`);const n=await e.blob(),t=URL.createObjectURL(n),o=document.createElement("a");o.href=t,o.download=a,document.body.appendChild(o),o.click(),o.remove(),URL.revokeObjectURL(t)}catch(e){console.error("Error downloading resume:",e),window.alert("No se pudo descargar el CV. Asegúrate de que el archivo /resume.pdf exista en la carpeta public y de que el servidor esté corriendo. Detalles: "+e.message)}}export{s as default};
